/**
 * Round-trip guarantees (SPEC §8.4, §13.6): parse(generate(x)) is canonicalize(x), and every
 * golden file is regenerated byte for byte from its parsed report.
 */
import { readdirSync, readFileSync } from 'node:fs';
import {
  generate1214,
  parse1214,
  type GenerateOptions,
  type Report1214Input,
} from '../../src/index.js';
import { canonicalize } from '../../src/normalize/canonical.js';
import { minimalInput } from '../fixtures/builders.js';

const OPTIONS: GenerateOptions = { today: () => '2025-03-31' };
const GOLDEN_DIR = new URL('../fixtures/golden/', import.meta.url);
const GOLDEN_SUFFIX = '.opcn';

const VARIANTS: ReadonlyArray<[string, Report1214Input, GenerateOptions]> = [
  ['minimal', minimalInput(), OPTIONS],
  ['tax year 2025', minimalInput({ taxYear: 2025 }), OPTIONS],
  [
    'every optional member of the skeleton',
    minimalInput({
      meta: { softwareName: 'My  Soft', saveDate: '2025-01-02' },
      company: {
        withholdingFileNumber: '940000001',
        vatFileNumber: '514000009',
        occupationDescription: '  ייצור\u00A0תוכנה ',
        booksAddress: 'רחוב יפו 10, ירושלים',
        email: 'office@example.com',
        fax: { prefix: '052', number: '7654321' },
      },
      declarations: {
        hasTaxPlanningAction: true,
        hadRelatedPartyTransactions: true,
        controlsBodyOfPersons: true,
        holdsRightsInBodyOfPersons: true,
        appliesAccountingStandards: true,
        directorsReceivedOpinion: true,
        tookReportablePosition: true,
      },
      shareholders: [
        {
          idNumber: '123456782',
          fullName: 'ישראל ישראלי',
          isControllingShareholder: true,
          dividendRightsPercent: 50,
          votingRightsPercent: 5.5,
          otherRightsPercent: 10.25,
          isMaterialShareholder: true,
          salaryMonths1To9: 90_000,
          salaryMonths10To12: 30_000,
          otherPayments: 1,
        },
        {
          idNumber: '999999998',
          fullName: 'אחזקות ציבור',
          isControllingShareholder: false,
          dividendRightsPercent: 50,
        },
      ],
    }),
    {},
  ],
  [
    'empty optional members and zero values',
    minimalInput({
      company: { occupationDescription: '  ', email: '', vatFileNumber: '000000000' },
      amounts: { '010': 0, '032': 0, '070': 0, '080': 0, '121': 0 },
      shareholders: [
        {
          idNumber: '123456782',
          fullName: 'ישראל ישראלי',
          isControllingShareholder: true,
          dividendRightsPercent: 100,
          isMaterialShareholder: false,
          salaryMonths1To9: 0,
        },
      ],
    }),
    OPTIONS,
  ],
  [
    'digit strings that need padding',
    minimalInput({
      company: {
        fileNumber: '12345',
        withholdingFileNumber: '7',
        fax: { prefix: '02', number: '7654321' },
      },
      shareholders: [
        {
          idNumber: '18',
          fullName: 'ישראל ישראלי',
          isControllingShareholder: true,
          dividendRightsPercent: 100,
        },
      ],
    }),
    OPTIONS,
  ],
  [
    'float residue in ×100 values and a blank software name',
    minimalInput({
      meta: { softwareName: '   ' },
      shareholders: [
        {
          idNumber: '123456782',
          fullName: 'ישראל ישראלי',
          isControllingShareholder: true,
          dividendRightsPercent: 0.7 + 0.2 + 0.1,
          votingRightsPercent: 1.1 + 2.2,
          otherRightsPercent: 10.1 + 20.2,
        },
      ],
    }),
    OPTIONS,
  ],
  [
    'amounts rounded half up',
    minimalInput({ amounts: { '081': 1000.5, '010': 0.4, '070': 2.5 } }),
    { ...OPTIONS, rounding: 'halfUp' },
  ],
];

const goldenNames = readdirSync(GOLDEN_DIR)
  .filter(file => file.endsWith(GOLDEN_SUFFIX))
  .map(file => file.slice(0, -GOLDEN_SUFFIX.length))
  .sort();

describe('round trip', () => {
  it.each(VARIANTS)('parse(generate(x)).report is canonicalize(x): %s', (_, input, options) => {
    const { bytes } = generate1214(input, options);
    const { report, issues } = parse1214(bytes);
    expect(report).toEqual(canonicalize(input, options));
    expect(issues.filter(issue => issue.severity === 'error')).toEqual([]);
  });

  it('reports the provisional layout of a 2025 report on both sides of the round trip', () => {
    const input = minimalInput({ taxYear: 2025 });
    const { bytes, warnings } = generate1214(input, OPTIONS);
    const ruleIds = ['struct.taxYear.provisionalLayout'];
    expect(warnings.map(issue => issue.ruleId)).toEqual(ruleIds);
    expect(parse1214(bytes).issues.map(issue => issue.ruleId)).toEqual(ruleIds);
  });

  it('parses the generated text like the generated bytes', () => {
    const { text, bytes } = generate1214(minimalInput(), OPTIONS);
    expect(parse1214(text)).toEqual(parse1214(bytes));
  });

  it('has golden files to check', () => {
    expect(goldenNames.length).toBeGreaterThan(0);
  });

  it.each(goldenNames)('%s.opcn is regenerated byte for byte from its parsed report', name => {
    const golden = new Uint8Array(readFileSync(new URL(`${name}${GOLDEN_SUFFIX}`, GOLDEN_DIR)));
    const { report, saveDate, softwareName } = parse1214(golden);
    const { bytes } = generate1214({ ...report, meta: { saveDate, softwareName } });
    expect(Buffer.from(bytes).equals(Buffer.from(golden))).toBe(true);
  });

  it.each(goldenNames)('%s.opcn parses to the canonical form of its input', async name => {
    const { input, options } = (await import(new URL(`${name}.input.ts`, GOLDEN_DIR).href)) as {
      input: Report1214Input;
      options: GenerateOptions;
    };
    const golden = new Uint8Array(readFileSync(new URL(`${name}${GOLDEN_SUFFIX}`, GOLDEN_DIR)));
    expect(parse1214(golden).report).toEqual(canonicalize(input, options));
  });
});
